def build_bst(vals):
    n = len(vals)
    L = [-1] * n
    R = [-1] * n
    for i in range(1, n):
        u = 0
        while True:
            if vals[i] < vals[u]:
                if L[u] < 0:
                    L[u] = i
                    break
                u = L[u]
            else:
                if R[u] < 0:
                    R[u] = i
                    break
                u = R[u]
    return L, R

def ser(vals, L, R):
    out = [str(vals[0])]
    q = [0]
    h = 0
    while h < len(q):
        u = q[h]
        h += 1
        for c in (L[u], R[u]):
            if c < 0:
                out.append('null')
            else:
                out.append(str(vals[c]))
                q.append(c)
    while out[-1] == 'null':
        out.pop()
    return ' '.join(out)

def make(n, lo, hi, mode, rng):
    pool = rng.sample(range(lo, hi + 1), n)
    if mode == 'right':
        pool.sort()
    elif mode == 'left':
        pool.sort(reverse=True)
    elif mode == 'zigzag':
        pool.sort()
        a, b = 0, n - 1
        z = []
        t = True
        while a <= b:
            if t:
                z.append(pool[a]); a += 1
            else:
                z.append(pool[b]); b -= 1
            t = not t
        pool = z
    elif mode == 'balanced':
        pool.sort()
        z = []
        st = [(0, n - 1)]
        while st:
            a, b = st.pop()
            if a > b:
                continue
            m = (a + b) // 2
            z.append(pool[m])
            st.append((m + 1, b))
            st.append((a, m - 1))
        pool = z
    L, R = build_bst(pool)
    return ser(pool, L, R)

